css:
* {
  box-sizing: border-box;
}

html,
body {
  width: 100%;
  height: 100%;
  margin: 0;
  overflow: hidden;
  background: transparent !important;
}

.motor-widget {
  position: relative;

  width: 100%;
  height: 100%;
  padding: 100px 60px 30px;

  container-type: size;
  background: transparent;
  color: #223441;

  font-family:
    Bahnschrift,
    "Segoe UI",
    Arial,
    sans-serif;

  user-select: none;
  pointer-events: none;
  opacity: var(--w-opacity, 1);
}

.motor-board {
  display: grid;
  grid-template-columns: 280px max-content;

  /* Se conserva la separación anterior entre columnas. */
  column-gap: clamp(50px, 5cqw, 85px);
  align-items: start;
  justify-content: center;

  width: 100%;
  margin: 0 auto;
  height: 100%;
  min-height: 0;
}

.motor-list {
  display: grid;
  gap: 18px;
  justify-items: center;
  align-content: space-between;
  height: 100%;
  min-height: 0;

  width: 280px;
}

.motor-group {
  width: 280px;
}

.motor-group-title,
.process-title {
  margin: 0 0 8px;

  color: #203541;
  font-size: clamp(18px, 1.4cqw, 23px);
  font-weight: 700;
  line-height: 1.2;
  text-align: center;
}

.motor-command-row {
  display: flex;
  align-items: flex-start;
  justify-content: center;
  gap: 28px;
}

.process-list {
  display: flex;
  align-items: flex-start;
  gap: clamp(28px, 4cqw, 65px);

  width: max-content;
}

.process-group {
  display: flex;
  flex: 0 0 220px;
  flex-direction: column;
  align-items: center;

  width: 220px;
}

.process-title {
  white-space: nowrap;
}

.command-unit {
  display: flex;
  align-items: center;
  justify-content: center;

  width: clamp(72px, 5.4cqw, 88px);
}

.command-shell {
  --core-light: #72ec77;
  --core-main: #20ca48;
  --core-dark: #07842d;
  --core-edge: #086b30;
  --mark-color: #174d27;
  --glow: rgba(26, 183, 69, 0.19);

  position: relative;

  display: grid;
  place-items: center;

  width: clamp(72px, 5.4cqw, 88px);
  aspect-ratio: 1;

  border: 2px solid #50646e;
  border-radius: 50%;

  background:
    linear-gradient(
      145deg,
      #fcfefe 0%,
      #e5ecef 30%,
      #bac7cd 72%,
      #eef3f5 100%
    );

  box-shadow:
    inset 0 2px 2px rgba(255, 255, 255, 0.95),
    inset 0 -3px 4px rgba(58, 75, 84, 0.2),
    0 3px 7px rgba(32, 48, 61, 0.18),
    0 0 9px var(--glow);
}

.command-shell--stop {
  --core-light: #ff7777;
  --core-main: #ed292d;
  --core-dark: #a61017;
  --core-edge: #930606;
  --mark-color: #651519;
  --glow: rgba(200, 39, 45, 0.17);
}

/* Aros metálicos concéntricos. */
.command-shell::before,
.command-shell::after {
  content: "";
  position: absolute;
  border-radius: 50%;
  pointer-events: none;
}

.command-shell::before {
  inset: 5px;
  border: 1px solid rgba(59, 78, 88, 0.55);
}

.command-shell::after {
  inset: 9px;
  border: 1px solid rgba(255, 255, 255, 0.83);
}

.command-core {
  position: relative;

  display: grid;
  place-items: center;

  width: 71%;
  height: 71%;

  border: 2px solid var(--core-edge);
  border-radius: 50%;

  background:
    radial-gradient(
      circle at 34% 27%,
      var(--core-light) 0%,
      var(--core-main) 53%,
      var(--core-dark) 100%
    );

  box-shadow:
    inset 0 2px 3px rgba(255, 255, 255, 0.27),
    inset 0 -4px 5px rgba(0, 0, 0, 0.18),
    0 1px 2px rgba(31, 48, 56, 0.32);
}

.command-octagon {
  position: absolute;

  width: 67%;
  aspect-ratio: 1;

  background: var(--mark-color);
  opacity: 0.58;

  clip-path: polygon(
    28% 0,
    72% 0,
    100% 28%,
    100% 72%,
    72% 100%,
    28% 100%,
    0 72%,
    0 28%
  );
}

.command-octagon::after {
  content: "";
  position: absolute;
  inset: 2px;

  background: var(--core-main);

  clip-path: polygon(
    28% 0,
    72% 0,
    100% 28%,
    100% 72%,
    72% 100%,
    28% 100%,
    0 72%,
    0 28%
  );
}

.command-symbol {
  position: relative;
  z-index: 1;

  color: var(--mark-color);
  opacity: 0.76;

  font-family:
    "IBM Plex Mono",
    Consolas,
    "Liberation Mono",
    monospace;

  font-size: clamp(13px, 1.1cqw, 18px);
  font-weight: 700;
  letter-spacing: -0.08em;
  line-height: 1;
}

.motor-footer {
  position: absolute;
  right: 60px;
  bottom: 18px;

  display: flex;
  align-items: center;
  justify-content: flex-end;
  height: 31px;
  padding-right: 4px;

  color: #20323b;
  font-size: clamp(17px, 1.35cqw, 22px);
  font-weight: 700;
  font-style: italic;
  white-space: nowrap;
}
/* Solo texto: encabezado transparente con la tipografía del ejemplo de recetas. */
.screen-header {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 70px;
  min-width: 0;
  padding: 14px 30px 0;
  overflow: hidden;
  background: transparent;
  font-family: Arial, Helvetica, sans-serif;
  user-select: none;
}

.screen-title {
  margin: 0;
  padding: 0;
  color: #0E5B67;
  font-size: 28px;
  font-weight: 700;
  line-height: 1.05;
  white-space: nowrap;
}

.screen-subtitle {
  margin: 5px 0 0;
  padding: 0;
  color: #728DA5;
  font-size: 14px;
  font-weight: 400;
  line-height: 1.3;
  white-space: nowrap;
}

