"use strict";

(function () {
  const DEFAULT_TITLE = "LÍNEA 3 / TABLERO DE MOTORES";
  const DEFAULT_SUBTITLE = "Arranque y parada de motores e inicio y fin del proceso";

  let headerTitle = null;
  let headerSubtitle = null;

  /* NOMBRE: Título//Subtítulo. Con Título// se oculta el subtítulo.
   * Sin NOMBRE se muestran ambos textos predeterminados.
   * Sin separador se personaliza solo el título.
   */
  function updateHeader(widget) {
    if (!headerTitle || !headerSubtitle) return;
    const name = widget && typeof widget.name === "string"
      ? widget.name.trim() : "";
    const separator = name.indexOf("//");
    const titleText = separator >= 0 ? name.slice(0, separator).trim() : name;
    const subtitleText = separator >= 0
      ? name.slice(separator + 2).trim() : DEFAULT_SUBTITLE;

    headerTitle.textContent = titleText || DEFAULT_TITLE;
    headerSubtitle.textContent = subtitleText;
    headerSubtitle.hidden = subtitleText === "";
    fitHeader();
  }

  function fitHeader() {
    [[headerTitle, 28], [headerSubtitle, 14]].forEach(function (entry) {
      const element = entry[0];
      if (!element || element.hidden) return;
      const size = entry[1];
      element.style.fontSize = size + "px";
      const available = element.clientWidth;
      if (available > 0 && element.scrollWidth > available) {
        element.style.fontSize = (size * available / element.scrollWidth) + "px";
      }
    });
  }

  let latestWidget = null;
  let headerObserver = null;



  const MOTORS = [
    "Ventiladores",
    "Motores Auxiliares",
    "Motor Principal",
    "Motor Extractor de Gases"
  ];

  const PROCESS_COMMANDS = [
    {
      title: "Inicio de Proceso",
      type: "start"
    },
    {
      title: "Fin de Proceso",
      type: "stop"
    }
  ];

  function make(tag, className, parent, text) {
    const element = document.createElement(tag);
    element.className = className;

    if (text !== undefined) {
      element.textContent = text;
    }

    parent.appendChild(element);
    return element;
  }

  function makeCommand(parent, type) {
    const unit = make(
      "div",
      "command-unit",
      parent
    );

    const shell = make(
      "div",
      "command-shell command-shell--" + type,
      unit
    );

    shell.setAttribute(
      "role",
      "img"
    );

    shell.setAttribute(
      "aria-label",
      type === "start"
        ? "Pulsador verde"
        : "Pulsador rojo"
    );

    const core = make(
      "div",
      "command-core",
      shell
    );

    make(
      "span",
      "command-octagon",
      core
    );

    make(
      "span",
      "command-symbol",
      core,
      "A-B"
    );
  }

  function makeMotorGroup(title, parent) {
    const group = make(
      "div",
      "motor-group",
      parent
    );

    make(
      "div",
      "motor-group-title",
      group,
      title
    );

    const commands = make(
      "div",
      "motor-command-row",
      group
    );

    makeCommand(commands, "start");
    makeCommand(commands, "stop");
  }

  function makeProcessGroup(item, parent) {
    const group = make(
      "div",
      "process-group",
      parent
    );

    make(
      "div",
      "process-title",
      group,
      item.title
    );

    makeCommand(group, item.type);
  }

  function buildWidget() {
    const motorList = document.getElementById(
      "motor-list"
    );

    const processList = document.getElementById(
      "process-list"
    );

    if (!motorList || !processList) return;

    motorList.replaceChildren();
    processList.replaceChildren();

    MOTORS.forEach(function (title) {
      makeMotorGroup(title, motorList);
    });

    PROCESS_COMMANDS.forEach(function (item) {
      makeProcessGroup(item, processList);
    });

    headerTitle = document.querySelector(".screen-title");
    headerSubtitle = document.querySelector(".screen-subtitle");
    updateHeader(latestWidget || window.WIDGET || null);

    if (typeof ResizeObserver !== "undefined") {
      headerObserver = new ResizeObserver(fitHeader);
      headerObserver.observe(document.querySelector(".screen-header"));
    } else {
      window.addEventListener("resize", fitHeader);
    }
  }

  /* Widget visual: no recibe variables del PLC. */
  window.onWidgetUpdate = function (widget) {
    latestWidget = widget;
    updateHeader(widget);
  };

  if (document.readyState === "loading") {
    document.addEventListener(
      "DOMContentLoaded",
      buildWidget,
      { once: true }
    );
  } else {
    buildWidget();
  }
})();
